using Logic.Contracts;

namespace Logic.CollisionResolution;

/// <summary>
/// A timestamp-based collision resolution strategy that uses high-resolution timestamps to ensure uniqueness.
/// This strategy is suitable for systems where time-based ordering is important and collision probability is moderate.
/// </summary>
public class TimestampCollisionResolutionStrategy : ICollisionResolutionStrategy
{
    /// <summary>
    /// Generates a unique short URL using timestamp-based collision resolution.
    /// </summary>
    /// <param name="baseShortUrl">The base short URL generated by the primary shortener.</param>
    /// <param name="attempt">The current attempt number (0-based).</param>
    /// <param name="longUrl">The original long URL being shortened.</param>
    /// <returns>A unique short URL using timestamp-based collision resolution.</returns>
    public string GenerateUniqueShortUrl(string baseShortUrl, int attempt, string longUrl)
    {
        ArgumentException.ThrowIfNullOrEmpty(baseShortUrl);
        ArgumentException.ThrowIfNullOrEmpty(longUrl);

        if (attempt < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(attempt), "Attempt number must be non-negative.");
        }

        // For attempt 0, return the base short URL (deterministic)
        if (attempt == 0)
        {
            return baseShortUrl;
        }

        // For retry attempts, use a timestamp-based approach
        // Use high-resolution timestamp (ticks) converted to a simple hash for compact representation
        long timestamp = DateTimeOffset.UtcNow.Ticks;
        string timestampSuffix = (timestamp % 1000000).ToString("D6"); // 6-digit suffix

        return $"{baseShortUrl}_{timestampSuffix}";
    }
}
